export type Filters=Omit<TicketListQuery,"page">;export function useTicketPages(filters:Filters,page:number){const client=useQueryClient();const normalized=normalizeQuery({...filters,page});const {status,q,pageSize,sort}=normalized;const query=useQuery({...ticketListOptions({...normalized,status:status??undefined}),placeholderData:keepPreviousData});useEffect(()=>{if(!query.isSuccess||query.isPlaceholderData||query.data.page!==page)return;const next=nextPage(query.data);if(next===undefined)return;void client.prefetchQuery(ticketListOptions({status:status??undefined,q,page:next,pageSize,sort}));},[client,query.data,query.isSuccess,query.isPlaceholderData,page,status,q,pageSize,sort]);return {query,pages:query.data?pageCount(query.data.total,pageSize):1};}export function infiniteTicketOptions(filters:Filters={}){const normalized=normalizeQuery(filters);const {page:ignored,...criteria}=normalized;return infiniteQueryOptions({queryKey:["tickets","infinite",criteria] as const,initialPageParam:1,queryFn:({queryKey,pageParam,signal})=>fetchTickets({...queryKey[2],status:queryKey[2].status??undefined,page:pageParam},signal),getNextPageParam:nextPage});}export function useInfiniteTickets(filters:Filters){return useInfiniteQuery(infiniteTicketOptions(filters));}

